### `manager_test.go`

```go
package kvblock

import (
	"errors"
	"math/rand"
	"reflect"
	"testing"
)

func newTestManager(t *testing.T, bs, nb int, hook EvictHook) *Manager {
	t.Helper()
	m, err := NewManager(bs, nb, hook)
	if err != nil {
		t.Fatalf("NewManager: %v", err)
	}
	return m
}

func mustAppend(t *testing.T, s *Sequence, vals ...uint64) {
	t.Helper()
	if err := s.Append(vals...); err != nil {
		t.Fatalf("append: %v", err)
	}
}

func mustToken(t *testing.T, s *Sequence, pos int, want uint64) {
	t.Helper()
	got, err := s.TokenAt(pos)
	if err != nil {
		t.Fatalf("TokenAt(%d): %v", pos, err)
	}
	if got != want {
		t.Fatalf("TokenAt(%d)=%d, want %d", pos, got, want)
	}
}

// TestAppendPartialBlockGrowth checks that a partial tail block keeps accepting
// tokens before a new physical block is appended.
func TestAppendPartialBlockGrowth(t *testing.T) {
	m := newTestManager(t, 4, 8, nil)
	s := m.NewSequence()
	mustAppend(t, s, 1, 2, 3)
	if s.Len() != 3 || len(s.Table()) != 1 {
		t.Fatalf("after 3 tokens: len=%d blocks=%d", s.Len(), len(s.Table()))
	}
	mustAppend(t, s, 4)
	if len(s.Table()) != 1 {
		t.Fatalf("filling partial block must not allocate: blocks=%d", len(s.Table()))
	}
	mustAppend(t, s, 5)
	if len(s.Table()) != 2 {
		t.Fatalf("spilling over must allocate: blocks=%d", len(s.Table()))
	}
	for i := 0; i < 5; i++ {
		mustToken(t, s, i, uint64(i+1))
	}
	if err := m.CheckInvariants(); err != nil {
		t.Fatal(err)
	}
	s.Release()
	if m.TotalRefs() != 0 {
		t.Fatalf("leak after release: total refs %d", m.TotalRefs())
	}
}

// TestCopyOnWriteSharedTail asserts that appending into a shared partial final
// block clones it, leaving the parent untouched and refcounts balanced.
func TestCopyOnWriteSharedTail(t *testing.T) {
	m := newTestManager(t, 4, 8, nil)
	parent := m.NewSequence()
	mustAppend(t, parent, 10, 20, 30)

	child, err := parent.Fork()
	if err != nil {
		t.Fatal(err)
	}
	shared := parent.Table()[0]
	if m.RefCount(shared) != 2 {
		t.Fatalf("shared refcount=%d, want 2", m.RefCount(shared))
	}

	// Child writes the 4th token into the shared partial block -> COW.
	mustAppend(t, child, 40)
	if m.RefCount(shared) != 1 {
		t.Fatalf("after COW parent refcount=%d, want 1", m.RefCount(shared))
	}
	if child.Table()[0] == parent.Table()[0] {
		t.Fatal("child still points at shared block after COW")
	}
	mustToken(t, child, 3, 40)
	if _, err := parent.TokenAt(3); !errors.Is(err, ErrInvalidPosition) {
		t.Fatalf("parent sees child token: %v", err)
	}
	mustToken(t, parent, 2, 30)
	if err := m.CheckInvariants(); err != nil {
		t.Fatal(err)
	}

	parent.Release()
	child.Release()
	if m.TotalRefs() != 0 {
		t.Fatalf("leak: total refs %d", m.TotalRefs())
	}
}

// TestSharedFullBlockNoCow asserts a full shared block is not cloned when the
// append starts a fresh logical block.
func TestSharedFullBlockNoCow(t *testing.T) {
	m := newTestManager(t, 2, 8, nil)
	parent := m.NewSequence()
	mustAppend(t, parent, 1, 2) // full block
	child, _ := parent.Fork()

	mustAppend(t, child, 3) // starts block 1, no COW of block 0
	if m.RefCount(parent.Table()[0]) != 2 {
		t.Fatalf("full shared block refcount=%d, want 2", m.RefCount(parent.Table()[0]))
	}
	if child.Table()[0] != parent.Table()[0] {
		t.Fatal("unexpected COW of a full shared block")
	}
	parent.Release()
	child.Release()
	if m.TotalRefs() != 0 {
		t.Fatalf("leak: total refs %d", m.TotalRefs())
	}
}

// TestLRUEvictionAndRecomputeHook verifies the least recently touched cached
// block is reclaimed first and the hook sees its payload.
func TestLRUEvictionAndRecomputeHook(t *testing.T) {
	type ev struct {
		id     BlockID
		tokens []uint64
	}
	var evicted []ev
	m := newTestManager(t, 1, 2, func(id BlockID, tok []uint64) {
		evicted = append(evicted, ev{id, tok})
	})
	s1 := m.NewSequence()
	mustAppend(t, s1, 100, 200) // block0=100 (older), block1=200 (newer)
	s1.Release()                // both cached; block0 has smaller lastTouch

	s2 := m.NewSequence()
	mustAppend(t, s2, 999) // must evict LRU cached block
	if len(evicted) != 1 {
		t.Fatalf("hook calls=%d, want 1", len(evicted))
	}
	if evicted[0].id != 0 {
		t.Fatalf("evicted block %d, want LRU block 0", evicted[0].id)
	}
	if len(evicted[0].tokens) != 1 || evicted[0].tokens[0] != 100 {
		t.Fatalf("evicted payload=%v, want [100]", evicted[0].tokens)
	}
	if m.EvictionCount() != 1 {
		t.Fatalf("eviction count=%d, want 1", m.EvictionCount())
	}
	s2.Release()
	if m.TotalRefs() != 0 {
		t.Fatalf("leak: total refs %d", m.TotalRefs())
	}
}

// TestFailClosedOnExhaustion checks allocation returns the typed error and
// never corrupts an existing table.
func TestFailClosedOnExhaustion(t *testing.T) {
	m := newTestManager(t, 1, 2, nil)
	s1 := m.NewSequence()
	mustAppend(t, s1, 7, 8)

	s2 := m.NewSequence()
	if err := s2.Append(9); !errors.Is(err, ErrNoBlockAvailable) {
		t.Fatalf("err=%v, want ErrNoBlockAvailable", err)
	}
	if s2.Len() != 0 || len(s2.Table()) != 0 {
		t.Fatalf("failed append mutated table: len=%d blocks=%d", s2.Len(), len(s2.Table()))
	}
	mustToken(t, s1, 0, 7)
	mustToken(t, s1, 1, 8)
	if s1.Len() != 2 {
		t.Fatalf("existing sequence changed: len=%d", s1.Len())
	}
	if err := m.CheckInvariants(); err != nil {
		t.Fatal(err)
	}

	// Releasing the blocker makes room.
	s1.Release()
	if err := s2.Append(9); err != nil {
		t.Fatalf("append after release: %v", err)
	}
	mustToken(t, s2, 0, 9)
	s2.Release()
	if m.TotalRefs() != 0 {
		t.Fatalf("leak: total refs %d", m.TotalRefs())
	}
}

// TestForkSavesAllocations measures that prefix sharing allocates strictly
// fewer physical blocks than independent construction.
func TestForkSavesAllocations(t *testing.T) {
	const (
		bs    = 4
		pre   = 10 // 3 blocks
		nKids = 5
	)

	// Baseline: every sequence grows the prefix itself.
	base := newTestManager(t, bs, 256, nil)
	for i := 0; i < nKids; i++ {
		s := base.NewSequence()
		for j := 0; j < pre; j++ {
			if err := s.Append(uint64(j)); err != nil {
				t.Fatal(err)
			}
		}
	}
	baseAllocs := base.AllocationCount()

	// Shared: one parent grows the prefix, the rest fork it.
	shared := newTestManager(t, bs, 256, nil)
	root := shared.NewSequence()
	for j := 0; j < pre; j++ {
		if err := root.Append(uint64(j)); err != nil {
			t.Fatal(err)
		}
	}
	for i := 0; i < nKids; i++ {
		if _, err := root.Fork(); err != nil {
			t.Fatal(err)
		}
	}
	sharedAllocs := shared.AllocationCount()

	if sharedAllocs >= baseAllocs {
		t.Fatalf("prefix sharing did not help: shared=%d base=%d", sharedAllocs, baseAllocs)
	}
	t.Logf("allocations: shared=%d baseline=%d", sharedAllocs, baseAllocs)
}

// TestRandomizedInterleavings drives random fork/append/release/evict traffic
// and checks invariants plus a leak-free finish.
func TestRandomizedInterleavings(t *testing.T) {
	for seed := int64(0); seed < 40; seed++ {
		rng := rand.New(rand.NewSource(seed))
		m := newTestManager(t, 1+rng.Intn(4), 8, nil)
		var live []*Sequence

		step := func(ok bool, err error) {
			if err != nil && !errors.Is(err, ErrNoBlockAvailable) {
				t.Fatalf("seed=%d unexpected err: %v", seed, err)
			}
			if err := m.CheckInvariants(); err != nil {
				t.Fatalf("seed=%d invariant: %v", seed, err)
			}
		}

		for i := 0; i < 400; i++ {
			if len(live) == 0 || rng.Intn(4) == 0 {
				s := m.NewSequence()
				if rng.Intn(3) > 0 {
					err := s.Append(randVals(rng, 1+rng.Intn(6))...)
					step(true, err)
					if err == nil {
						live = append(live, s)
					} else {
						s.Release()
					}
				} else {
					live = append(live, s)
				}
				continue
			}
			k := rng.Intn(len(live))
			s := live[k]
			switch rng.Intn(3) {
			case 0:
				err := s.Append(randVals(rng, 1+rng.Intn(6))...)
				step(true, err)
			case 1:
				c, err := s.Fork()
				if err != nil {
					t.Fatalf("seed=%d fork: %v", seed, err)
				}
				live = append(live, c)
			case 2:
				s.Release()
				live = append(live[:k], live[k+1:]...)
			}
		}

		for _, s := range live {
			s.Release()
		}
		if err := m.CheckInvariants(); err != nil {
			t.Fatalf("seed=%d final invariant: %v", seed, err)
		}
		if m.TotalRefs() != 0 || m.InUse() != 0 {
			t.Fatalf("seed=%d leak: totalRefs=%d inUse=%d", seed, m.TotalRefs(), m.InUse())
		}
		// Every token of every surviving table mapped to a valid block.
		for _, s := range live {
			if len(s.Table()) != 0 || s.Len() != 0 {
				t.Fatalf("seed=%d released sequence retained state", seed)
			}
		}
	}
}

// TestFailClosedRollsBackPartialReservation exercises the case where a COW plus
// a new block are both required but the pool can only satisfy the first
// reservation: the partial reservation must be rolled back and the table left
// untouched.
func TestFailClosedRollsBackPartialReservation(t *testing.T) {
	m := newTestManager(t, 2, 3, nil)

	parent := m.NewSequence()
	mustAppend(t, parent, 1) // block0 partial, tokens=1
	child, err := parent.Fork()
	if err != nil {
		t.Fatal(err)
	}

	// Pin one more block so only a single evictable block remains.
	pinner := m.NewSequence()
	mustAppend(t, pinner, 5)

	shared := parent.Table()[0]
	before := child.Table()

	// Needs COW (block0 shared) + one new block, but only one block is free.
	if err := child.Append(2, 3); !errors.Is(err, ErrNoBlockAvailable) {
		t.Fatalf("err=%v, want ErrNoBlockAvailable", err)
	}
	if child.Len() != 1 {
		t.Fatalf("child len=%d, want 1", child.Len())
	}
	if len(child.Table()) != 1 || child.Table()[0] != shared {
		t.Fatalf("child table changed after failed append: %v", child.Table())
	}
	if m.RefCount(shared) != 2 {
		t.Fatalf("shared refcount=%d, want 2", m.RefCount(shared))
	}
	if m.RefCount(2) != 0 {
		t.Fatalf("partial reservation leaked: block2 refcount=%d", m.RefCount(2))
	}
	if !reflect.DeepEqual(before, child.Table()) {
		t.Fatalf("table mutated: before=%v after=%v", before, child.Table())
	}
	if err := m.CheckInvariants(); err != nil {
		t.Fatal(err)
	}

	// Once the parent releases its reference, the COW append fits.
	parent.Release()
	if err := child.Append(2, 3); err != nil {
		t.Fatalf("append after room: %v", err)
	}
	mustToken(t, child, 1, 2)
	mustToken(t, child, 2, 3)
	child.Release()
	pinner.Release()
	if m.TotalRefs() != 0 {
		t.Fatalf("leak: total refs %d", m.TotalRefs())
	}
}

