	v := make([]uint64, n)
	for i := range v {
		v[i] = uint64(rng.Intn(1 << 20))
	}
	return v
}

// TestEveryTokenMapsToValidBlock stress-checks token->block resolution.
func TestEveryTokenMapsToValidBlock(t *testing.T) {
	m := newTestManager(t, 3, 32, nil)
	root := m.NewSequence()
	for i := 0; i < 7; i++ {
		mustAppend(t, root, uint64(i))
	}
	kids := []*Sequence{root}
	for i := 0; i < 4; i++ {
		c, err := kids[len(kids)-1].Fork()
		if err != nil {
			t.Fatal(err)
		}
		kids = append(kids, c)
	}
	for _, s := range kids {
		for pos := 0; pos < s.Len(); pos++ {
			id, err := s.BlockForToken(pos)
			if err != nil {
				t.Fatalf("seq %d pos %d: %v", s.ID(), pos, err)
			}
			if m.RefCount(id) < 1 {
				t.Fatalf("seq %d pos %d -> unreferenced block %d", s.ID(), pos, id)
			}
			mustToken(t, s, pos, uint64(pos))
		}
	}
	if err := m.CheckInvariants(); err != nil {
		t.Fatal(err)
	}
	for _, s := range kids {
		s.Release()
	}
	if m.TotalRefs() != 0 {
		t.Fatalf("leak: total refs %d", m.TotalRefs())
	}
}
